"""Read integers from numbers.txt, square them on four workers, and print the sum of the even squares."""

import tolquane as tq

PATH = "numbers.txt"


@tq.source
def lines():
    # The real source: one line per item, streamed straight from the file.
    with open(PATH) as f:
        yield from f


@tq.node
def parse(line: str) -> int:
    # Text to integer; blank lines are dropped rather than sent on.
    text = line.strip()
    if not text:
        return tq.SKIP
    return int(text)


@tq.node
def square(n: int) -> int:
    # Pure function, so it can run on several workers at once.
    return n * n


@tq.node
def keep_even(n: int) -> int:
    # Filter: SKIP sends nothing, so odd squares disappear here.
    return n if n % 2 == 0 else tq.SKIP


class Total:
    # Stateful and must see every item, so it is a single class sink, not a farm.
    def __init__(self) -> None:
        self.total = 0

    def __call__(self, n: int) -> None:
        self.total += n

    def on_end(self, ctx: tq.Context) -> None:
        print(f"sum of even squares: {self.total}")


def build(source=None):
    start = tq.from_iterable(source) if source is not None else lines
    return start >> parse >> tq.farm(square, workers=4) >> keep_even >> tq.sink(Total)


def main() -> None:
    tq.run(build())


if __name__ == "__main__":
    main()
